// scripts/add-generated-header.mjs
import fs from 'fs';

const FILE = process.argv[2];

if (!FILE) {
  throw new Error('No file path provided to add-generated-header');
}
console.log('Adding generated header to', FILE);

const HEADER = `/*
 * ======================================================
 * ⚠️ THIS FILE IS AUTO-GENERATED — DO NOT EDIT MANUALLY
 * ------------------------------------------------------
 * Generated by OpenAPI tooling
 *
 * Any changes made to this file will be overwritten.
 * ======================================================
 */

`;

let content = fs.readFileSync(FILE, 'utf8');

// Remove existing openapi-typescript header if present
const openapiHeaderRegex = /^\/\*\*[\s\S]*?\*\/\s*/;
content = content.replace(openapiHeaderRegex, '');

// Add our custom header
fs.writeFileSync(FILE, HEADER + content);
